using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Reflection;

namespace DisplayShot
{
    /// <summary>Images embedded in the exe (generated by tools/make_assets.py). Resource names are the
    /// file names, e.g. "tool-rect.png".</summary>
    internal static class Assets
    {
        static readonly Dictionary<string, Bitmap> cache = new Dictionary<string, Bitmap>();
        static readonly Dictionary<string, Bitmap> scaled = new Dictionary<string, Bitmap>();

        /// <summary>A toolbar glyph (stored at 4x) resampled to <paramref name="size"/> px, for the current
        /// monitor's scale. Cached per size.</summary>
        public static Bitmap Glyph(string name, int size)
        {
            string key = name + "@" + size;
            Bitmap bmp;
            if (scaled.TryGetValue(key, out bmp)) return bmp;
            Bitmap src = Get(name + ".png");
            if (src == null) return null;
            int w = src.Width * size / 128, h = src.Height * size / 128;   // 128 px = 32 design units
            bmp = new Bitmap(System.Math.Max(1, w), System.Math.Max(1, h));
            using (Graphics g = Graphics.FromImage(bmp))
            {
                g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = PixelOffsetMode.HighQuality;
                g.DrawImage(src, new Rectangle(0, 0, bmp.Width, bmp.Height));
            }
            scaled[key] = bmp;
            return bmp;
        }

        /// <summary>Returns the embedded image, or null when it doesn't exist.</summary>
        public static Bitmap Get(string name)
        {
            Bitmap bmp;
            if (cache.TryGetValue(name, out bmp)) return bmp;
            using (Stream s = Assembly.GetExecutingAssembly().GetManifestResourceStream(name))
            {
                // Copy out of the stream: GDI+ requires the stream to stay open for the bitmap's lifetime.
                bmp = s == null ? null : new Bitmap(Image.FromStream(s));
            }
            cache[name] = bmp;
            return bmp;
        }

    }
}
